{"inp":{"code":"# Compute target prices for various EV/EBITDA multiples and P/VPA multiples
shares = 1117226694.9152544
divida_liq = 3.421446e10
ebitda = 9527547334.664942  # implied from EV/EBITDA
multiples = [8.0, 9.0, 10.0, 11.0]
results = {}
for m in multiples:
    ev_target = ebitda * m
    market_cap_target = ev_target - divida_liq
    price_target = market_cap_target / shares
    results[f'EV/EBITDA_{m}'] = {'ev_target': ev_target, 'market_cap_target': market_cap_target, 'price_target': price_target}
# P/VPA targets
p_vpa_multiples = [1.6, 1.7, 1.85, 2.0]
vpa = 18.88
for m in p_vpa_multiples:
    price_pvpa = vpa * m
    results[f'P/VPA_{m}'] = {'price_pvpa': price_pvpa}
print(results)"}}
